-- 30 assessment questions in eight categories, based on the basic safeguards in CIS Controls v8 (IG1)
-- and mapped to POPIA security duties. Columns: category, text, guidance, remediation, popia_ref, severity, weight, sort_order.

insert into questions (category, text, guidance, remediation, popia_ref, severity, weight, sort_order) values
('Access control', 'Is multi-factor authentication (MFA) turned on for email and the other cloud accounts that hold client information?', 'A stolen password alone should not be enough to open your email or file storage.', 'Turn on MFA for every user, starting with email and file storage. Use an authenticator app rather than SMS where you can.', 'POPIA s19', 'critical', 5, 1),
('Access control', 'Does every staff member have their own login, with no shared passwords?', 'Shared logins make it impossible to know who opened or changed client files.', 'Create an individual account for each person and remove shared ones.', 'POPIA s19', 'high', 4, 2),
('Access control', 'Can staff only open the client information they need for their job?', 'Fewer people with access means less damage if one account is compromised.', 'Review who can open each folder or system and remove access that is not needed.', 'POPIA s19', 'high', 3, 3),
('Access control', 'Is access removed on the same day someone leaves the firm?', 'Former staff who keep access are a common source of data leaks.', 'Keep a leaver checklist: disable accounts, collect devices and change any shared secrets.', 'POPIA s19', 'medium', 3, 4),
('Access control', 'Do staff use a password manager or follow a rule for long, unique passwords?', 'Reused and weak passwords are how most accounts are taken over.', 'Provide a business password manager and set a minimum length of 12 characters.', 'POPIA s19', 'medium', 2, 5),

('Devices and software', 'Are laptops and phones that hold client data protected with full-disk encryption?', 'If a device is lost or stolen, encryption keeps the data unreadable.', 'Turn on BitLocker (Windows) or FileVault (Mac) and store the recovery keys safely.', 'POPIA s19', 'high', 4, 6),
('Devices and software', 'Are operating systems and business software set to update automatically?', 'Most attacks use known flaws that updates already fix.', 'Turn on automatic updates and replace systems that no longer receive security updates.', 'POPIA s19', 'high', 4, 7),
('Devices and software', 'Does every computer have up-to-date antivirus or endpoint protection?', 'Basic protection stops a large share of common malware.', 'Install a managed endpoint protection product on every computer and check it reports as healthy.', 'POPIA s19', 'medium', 3, 8),
('Devices and software', 'Do you keep a current list of the computers, phones and key software the firm uses?', 'You cannot protect what you do not know you have.', 'Keep a simple register of devices, who uses them and which key software runs on them.', 'POPIA s19', 'medium', 2, 9),
('Devices and software', 'Do screens lock automatically, and are office devices and paper files physically secured?', 'Unattended screens and open filing cabinets expose client information.', 'Set screens to lock after a few minutes and keep paper files and spare devices in a locked place.', 'POPIA s19', 'low', 2, 10),

('Data protection', 'Do you know where client personal information is stored, including cloud services and email?', 'Protecting personal information starts with knowing where it is.', 'List every place client data is kept and who can access it.', 'POPIA s19', 'high', 3, 11),
('Data protection', 'Is sensitive client information (ID numbers, tax and banking details, health records) kept in protected, access-controlled locations?', 'Sensitive information needs stronger protection than everyday documents.', 'Move sensitive records into a restricted folder or system with access limited to named people.', 'POPIA s19', 'high', 4, 12),
('Data protection', 'Do you delete or archive client records you no longer need?', 'POPIA limits keeping personal information for longer than necessary.', 'Set a retention period for each type of record and delete or securely archive on schedule.', 'POPIA s14', 'medium', 2, 13),
('Data protection', 'Do you send client information through secure methods rather than plain email attachments or messaging apps?', 'Email and chat apps are easy to intercept or misdirect.', 'Use a secure file-sharing link with a password or expiry date.', 'POPIA s19', 'medium', 3, 14),

('Backups', 'Are client files and systems backed up automatically at least once a day?', 'Backups are your way back from ransomware, mistakes and hardware failure.', 'Set up automatic daily backups and check the reports each week.', 'POPIA s19', 'high', 4, 15),
('Backups', 'Is at least one backup copy kept offline or separate from your main network?', 'Ransomware can encrypt backups that are connected to your network.', 'Keep one copy in a separate cloud account or on an offline drive that staff cannot overwrite.', 'POPIA s19', 'high', 4, 16),
('Backups', 'Have you tested restoring from a backup in the last six months?', 'A backup you have never restored may not work when you need it.', 'Restore a few files and then a full system as a test, and note how long it takes.', 'POPIA s19', 'medium', 3, 17),

('Email and browser protection', 'Is spam and phishing filtering turned on for business email?', 'Most attacks on small firms start with a malicious email.', 'Enable the advanced filtering in your email service and block external messages that pretend to be your staff.', 'POPIA s19', 'high', 3, 18),
('Email and browser protection', 'Must staff confirm by phone, using a known number, before paying a new account or changing bank details?', 'Fake payment requests are one of the most common frauds against small firms.', 'Make a call-back to a known number a required step for every change of bank details.', 'POPIA s19', 'high', 4, 19),
('Email and browser protection', 'Are web browsers kept up to date, with risky extensions blocked or reviewed?', 'Outdated browsers and unknown extensions are an easy way in.', 'Allow only approved browser extensions and keep browsers on automatic updates.', 'POPIA s19', 'medium', 2, 20),
('Email and browser protection', 'Is email authentication (SPF, DKIM and DMARC) set up for your domain?', 'It makes it harder for criminals to send emails that look like they come from your firm.', 'Ask your IT provider or domain host to publish SPF and DKIM records and a DMARC policy.', 'POPIA s19', 'medium', 2, 21),

('Incident response', 'Do you have a written plan for what to do if client data is lost, stolen or accessed by someone unauthorised?', 'POPIA requires you to notify the Information Regulator and affected people of a security compromise.', 'Write a one-page plan: who to call, how to contain the problem, who decides, and how to notify.', 'POPIA s22', 'critical', 5, 22),
('Incident response', 'Does someone know how to report a security compromise to the Information Regulator and to affected clients?', 'A prepared process saves time when it matters most.', 'Learn the Regulator’s notification process and prepare a template message for clients.', 'POPIA s22', 'high', 4, 23),
('Incident response', 'Has the firm’s Information Officer been identified and registered with the Information Regulator?', 'Every business has an Information Officer, by default the head of the business, who has duties under POPIA.', 'Confirm who the Information Officer is, register them with the Regulator and note their duties.', 'POPIA s55', 'medium', 3, 24),
('Incident response', 'Do you keep a log of security incidents and near misses?', 'Patterns in small incidents show where bigger ones may come from.', 'Keep a simple log with the date, what happened, what you did and what you changed afterwards.', 'POPIA s22', 'low', 2, 25),

('Staff awareness', 'Have all staff had security awareness training in the last 12 months?', 'People are the most common way in, and training is cheap compared with a breach.', 'Run a short annual session on phishing, passwords and handling client data, and keep a record of attendance.', 'POPIA s19', 'high', 3, 26),
('Staff awareness', 'Do new staff receive security and privacy guidance when they join?', 'The first weeks are when habits are formed.', 'Add a security and privacy briefing to your onboarding checklist.', 'POPIA s19', 'medium', 2, 27),
('Staff awareness', 'Do staff know not to use personal email or personal cloud storage for client information?', 'Client data on personal accounts is outside the firm’s control.', 'Write a short rule on approved tools and share it with all staff.', 'POPIA s19', 'medium', 2, 28),

('Supplier management', 'Do you have a written agreement with each supplier that handles client information, such as cloud, IT support and bookkeeping services?', 'POPIA expects a written contract with anyone processing personal information for you.', 'Put written operator agreements in place that cover security measures and breach notification.', 'POPIA s21', 'high', 4, 29),
('Supplier management', 'Do you check how your IT provider and key suppliers protect your data, and do they agree to tell you promptly about any breach?', 'Your suppliers’ weaknesses become your risk.', 'Ask each key supplier how they secure your data and agree in writing that they will tell you promptly about any breach.', 'POPIA s21', 'medium', 3, 30);
